public static class CsvBatch
{
    public static IReadOnlyList<string> Split(string row, char delimiter = ',')
        => row.Split(delimiter);

    public static IReadOnlyList<string> Split(string row, char delimiter, bool trim)
        => trim
            ? row.Split(delimiter).Select(s => s.Trim()).ToArray()
            : row.Split(delimiter);
}

var cells = CsvBatch.Split("a,b,c");
var trimmed = CsvBatch.Split(row: " a , b ", delimiter: ',', trim: true);

public static class Logger
{
    public static void Scope(params IEnumerable<string> tags)
    {
        foreach (var tag in tags)
            Console.WriteLine($"[tag] {tag}");
    }
}

Logger.Scope("attemptId", "userId", "score");
Logger.Scope(["attemptId", "userId", "score"]);

public static bool AnyEmptyRow(params ReadOnlySpan<char> rows)
{
    foreach (var row in rows)
    {
        if (row.IsEmpty)
            return true;
    }
    return false;
}

// Comma-separated spans — no string[] allocation:
AnyEmptyRow("a,b,c".AsSpan(), ReadOnlySpan<char>.Empty);

struct Counter { public int Value; }

class ScoreBoard { public int Total; }

static void BumpStruct(Counter c) { c.Value++; }
static void BumpClass(ScoreBoard s) { s.Total++; }

var counter = new Counter();
BumpStruct(counter); // counter.Value is still 0

var board = new ScoreBoard();
BumpClass(board); // board.Total is now 1
